:root {
  color-scheme: dark;
  --bg: #0a0c0f;
  --bg-elevated: #12161c;
  --ink: #f3f0e8;
  --muted: #9a9488;
  --line: #2a2f38;
  --copper: #d4a574;
  --copper-dim: #8c6b4a;
  --signal: #7dd3a8;
  --signal-dim: #3d6b56;
  --danger: #f0a8a8;
  --radius: 14px;
  --font-display: "Instrument Serif", Georgia, serif;
  --font-body: "DM Sans", "Segoe UI", sans-serif;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--ink);
  line-height: 1.45;
}

.grid-noise {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(212, 165, 116, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(212, 165, 116, 0.04) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(circle at 30% 20%, black, transparent 70%);
}

.shell {
  position: relative;
  max-width: 980px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3rem) 1.25rem 4rem;
}

.hero {
  display: grid;
  gap: 1.5rem;
  align-items: end;
  margin-bottom: 1.75rem;
}

@media (min-width: 720px) {
  .hero {
    grid-template-columns: 1.2fr 0.8fr;
  }
}

.hero h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 7vw, 4.2rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.02em;
}

.hero h1 em {
  font-style: italic;
  color: var(--copper);
}

.lede {
  margin: 0.75rem 0 0;
  max-width: 38ch;
  color: var(--muted);
  font-size: 1.05rem;
}

.hero-ticker {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(145deg, var(--bg-elevated), #0d1014);
  padding: 0.85rem 1rem;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.ticker-row {
  display: grid;
  grid-template-columns: 3.5rem 1fr auto;
  gap: 0.5rem;
  align-items: center;
  padding: 0.35rem 0;
  border-bottom: 1px dashed var(--line);
  font-size: 0.9rem;
}

.ticker-row:last-child {
  border-bottom: none;
}

.tag {
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--copper);
  font-size: 0.75rem;
}

.up {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.muted {
  color: var(--muted);
  font-size: 0.8rem;
}

.card {
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 4px);
  background: var(--bg-elevated);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
}

.panel-form {
  padding: 1.25rem 1.25rem 1.35rem;
  display: grid;
  gap: 1rem;
  animation: rise 0.55s var(--ease-out) both;
}

.panel-results {
  margin-top: 1rem;
  padding: 1.25rem;
  animation: rise 0.55s var(--ease-out) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.form-head h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.65rem;
  font-weight: 400;
}

.status-line {
  margin: 0.35rem 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.status-line .on {
  color: var(--signal);
}

label {
  display: grid;
  gap: 0.45rem;
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}

input,
select,
button {
  font: inherit;
}

input,
select {
  padding: 0.8rem 0.95rem;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: #0c0f13;
  color: var(--ink);
  transition: border-color 0.2s var(--ease-out), box-shadow 0.2s var(--ease-out);
}

input:focus,
select:focus {
  outline: none;
  border-color: var(--copper-dim);
  box-shadow: 0 0 0 3px rgba(212, 165, 116, 0.15);
}

button[type="submit"] {
  border: none;
  border-radius: 10px;
  padding: 0.95rem 1.1rem;
  background: linear-gradient(135deg, var(--copper), #b88452);
  color: #1a1208;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s var(--ease-out), filter 0.15s;
}

button[type="submit"]:hover:not(:disabled) {
  filter: brightness(1.05);
  transform: translateY(-1px);
}

button:disabled {
  opacity: 0.55;
  cursor: wait;
}

.hidden {
  display: none;
}

.loading {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--muted);
}

.spinner {
  width: 1.1rem;
  height: 1.1rem;
  border: 2px solid var(--line);
  border-top-color: var(--copper);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.price-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 0.75rem;
  margin: 1rem 0 0.5rem;
}

.stat {
  background: #0c0f13;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.8rem;
}

.stat span {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.stat strong {
  display: block;
  margin-top: 0.25rem;
  font-size: 1.55rem;
  font-variant-numeric: tabular-nums;
}

.stat.featured {
  border-color: var(--copper-dim);
  background: linear-gradient(160deg, #141820, #0f1218);
}

.meta-row {
  font-size: 0.88rem;
  color: var(--muted);
}

.meta-row code {
  color: var(--signal);
  font-size: 0.82rem;
}

.table-wrap {
  overflow-x: auto;
  margin-top: 0.75rem;
  border: 1px solid var(--line);
  border-radius: 10px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.84rem;
}

th,
td {
  text-align: left;
  padding: 0.55rem 0.65rem;
  border-bottom: 1px solid var(--line);
}

th {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  background: #0c0f13;
}

tr:last-child td {
  border-bottom: none;
}

.brief {
  margin-top: 1rem;
  padding: 1rem;
  border-left: 3px solid var(--copper);
  background: #0c0f13;
  line-height: 1.55;
  border-radius: 0 10px 10px 0;
}

.copy-row {
  margin-top: 0.85rem;
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.ghost {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 0.55rem 0.95rem;
  cursor: pointer;
}

.ghost:hover {
  border-color: var(--copper-dim);
}

.error {
  color: var(--danger);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

type Quote = {
  suggested_price: number;
  quick_sale_price: number;
  hold_price: number;
  confidence: string;
  comp_count: number;
  method: string;
  listing_brief: string;
  comps: Array<{
    title: string;
    platform: string;
    sold_price: number;
    condition_grade: string;
    source: string;
  }>;
};

type Health = {
  database: boolean;
  serpapi: boolean;
  tabpfn: boolean;
  gemma: boolean;
};

const form = document.querySelector<HTMLFormElement>("#quote-form")!;
const results = document.querySelector<HTMLElement>("#results")!;
const submitBtn = document.querySelector<HTMLButtonElement>("#submit-btn")!;
const statusLine = document.querySelector<HTMLElement>("#integration-status")!;

void loadHealth();

async function loadHealth() {
  try {
    const res = await fetch("/api/health");
    const h = (await res.json()) as Health;
    const parts = [
      h.gemma ? '<span class="on">Gemma</span>' : "Gemma off",
      h.tabpfn ? '<span class="on">TabPFN</span>' : "TabPFN off",
      h.database ? '<span class="on">Tiger</span>' : "seed comps",
      h.serpapi ? '<span class="on">SerpApi</span>' : "SerpApi off",
    ];
    statusLine.innerHTML = `Pipeline: ${parts.join(" · ")}`;
  } catch {
    statusLine.textContent = "API offline — start the server with npm run dev";
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const title = (
    document.querySelector<HTMLInputElement>("#title")!.value ?? ""
  ).trim();
  const condition =
    document.querySelector<HTMLSelectElement>("#condition")!.value;

  submitBtn.disabled = true;
  results.classList.remove("hidden");
  results.innerHTML = `
    <div class="loading" role="status">
      <span class="spinner" aria-hidden="true"></span>
      <span>Extracting specs, pulling comps, running TabPFN…</span>
    </div>
  `;

  try {
    const res = await fetch("/api/quote", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title, condition }),
    });
    const data = (await res.json()) as Quote & { error?: string };
    if (!res.ok) {
      throw new Error(data.error ?? "Request failed");
    }
    renderQuote(data);
  } catch (err) {
    results.innerHTML = `<p class="error">${err instanceof Error ? err.message : "Unknown error"}</p>`;
  } finally {
    submitBtn.disabled = false;
  }
});

function renderQuote(q: Quote) {
  const rows = q.comps
    .map(
      (c) =>
        `<tr><td>${escapeHtml(c.title)}</td><td>${c.platform}</td><td>$${c.sold_price}</td><td>${c.source}</td></tr>`,
    )
    .join("");

  results.innerHTML = `
    <h2 class="results-title">Your wire</h2>
    <div class="price-grid">
      <div class="stat featured"><span>List at</span><strong>$${q.suggested_price}</strong></div>
      <div class="stat"><span>Quick sale</span><strong>$${q.quick_sale_price}</strong></div>
      <div class="stat"><span>Hold</span><strong>$${q.hold_price}</strong></div>
      <div class="stat"><span>Confidence</span><strong>${q.confidence}</strong></div>
    </div>
    <p class="meta-row">${q.comp_count} comps · <code>${q.method}</code></p>
    <div class="table-wrap">
      <table>
        <thead><tr><th>Comp</th><th>Platform</th><th>Sold</th><th>Source</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div class="brief" id="brief">${escapeHtml(q.listing_brief)}</div>
    <div class="copy-row">
      <button type="button" class="ghost" id="copy-brief">Copy listing brief</button>
    </div>
  `;

  document.querySelector("#copy-brief")?.addEventListener("click", async () => {
    await navigator.clipboard.writeText(q.listing_brief);
  });
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

