import type { ConditionGrade } from "../types.js";

/** Marketplace-facing condition options (broader than pricing buckets). */
export const MARKETPLACE_CONDITIONS: Array<{
  value: string;
  label: string;
  pricing_grade: ConditionGrade;
  marketing_note: string;
}> = [
  {
    value: "new_sealed",
