import type { ExtractedSpecs } from "../types.js";

/** One-line product label without duplicating brand in model_family. */
export function formatProductSummary(specs: ExtractedSpecs): string {
  const brand = specs.brand.trim();
  const model = specs.model_family.trim();
  if (!model || brand === "Unknown") {
    return model || brand || "Item";
  }
  const modelLower = model.toLowerCase();
  const brandLower = brand.toLowerCase();
  let name =
    modelLower.startsWith(brandLower) || modelLower.includes(brandLower)
      ? model
      : `${brand} ${model}`;
  if (specs.storage_gb) {
    name += `, ${specs.storage_gb}GB`;
  }
  return name;
}

import { MARKETPLACE_CONDITIONS } from "./conditions.js";

export const PLATFORM_IDS = ["ebay", "etsy", "stockx", "facebook"] as const;
export type PlatformId = (typeof PLATFORM_IDS)[number];

export type PlatformMeta = {
  id: PlatformId;
  label: string;
  tagline: string;
  default?: boolean;
};

export const PLATFORMS: PlatformMeta[] = [
  {
    id: "ebay",
    label: "eBay",
    tagline: "Title, item specifics, condition, and shipping for the listing form",
    default: true,
  },
  {
    id: "etsy",
    label: "Etsy",
    tagline: "Title, tags, materials, and handmade/vintage fields",
  },
  {
    id: "stockx",
    label: "StockX",
    tagline: "Sell flow: product match, size/box, and ask price",
  },
  {
    id: "facebook",
    label: "Facebook Marketplace",
    tagline: "Short title, condition, price, and local pickup notes",
  },
];

/** Map internal condition value → marketplace label shown on that platform's form. */
const EBAY_CONDITION: Record<string, string> = {
  new_sealed: "New",
