const ETSY_CONDITION: Record<string, string> = {
  new_sealed: "New",
  new_open_box: "New",
  like_new: "Like new",
  excellent: "Like new",
  very_good: "Good",
  good: "Good",
  acceptable: "Fair",
  fair: "Fair",
  poor: "Poor",
