};

const STOCKX_CONDITION: Record<string, string> = {
  new_sealed: "New",
  new_open_box: "New (open box)",
  like_new: "Used",
  excellent: "Used",
  very_good: "Used",
  good: "Used",
  acceptable: "Used",
  fair: "Used",
  poor: "Used",
