input.contents:
import { MARKETPLACE_CONDITIONS, normalizeConditionValue } from "./conditions.js";

export const PLATFORM_IDS = ["ebay", "etsy", "stockx", "facebook"] as const;
export type PlatformId = (typeof PLATFORM_IDS)[number];

export type PlatformMeta = {
  id: PlatformId;
  label: string;
  tagline: string;
  default?: boolean;
};

export const PLATFORMS: PlatformMeta[] = [
  {
    id: "ebay",
    label: "eBay",
    tagline: "Title and description first—eBay handles shipping in its own flow",
    default: true,
  },
  {
    id: "etsy",
    label: "Etsy",
    tagline: "Title and description; add Etsy-only fields only if you sell there",
  },
  {
    id: "stockx",
    label: "StockX",
    tagline: "Match the catalog, then set ask price in StockX",
  },
  {
    id: "facebook",
    label: "Facebook Marketplace",
    tagline: "Title, condition, description—price and delivery in Meta’s UI",
  },
];

const EBAY_CONDITION: Record<string, string> = {
  new: "New",
  open_box: "Open box",
  used: "Used",
  refurbished: "Manufacturer refurbished",
  for_parts: "For parts or not working",
};

const ETSY_CONDITION: Record<string, string> = {
  new: "New",
  open_box: "New",
  used: "Good",
  refurbished: "Like new",
  for_parts: "Poor",
};

const STOCKX_CONDITION: Record<string, string> = {
  new: "New",
  open_box: "New (open box)",
  used: "Used",
  refurbished: "New",
  for_parts: "Used — defects",
};

const FACEBOOK_CONDITION: Record<string, string> = {
  new: "New",
  open_box: "New",
  used: "Used — Good",
  refurbished: "Used — Like new",
  for_parts: "Used — Poor",
};

export function platformConditionLabel(
  platform: PlatformId,
  marketplaceConditionValue: string,
): string {
  const key = normalizeConditionValue(marketplaceConditionValue);
  const fallback =
    MARKETPLACE_CONDITIONS.find((c) => c.value === key)?.label ?? "Used";
  const maps: Record<PlatformId, Record<string, string>> = {
    ebay: EBAY_CONDITION,
    etsy: ETSY_CONDITION,
    stockx: STOCKX_CONDITION,
    facebook: FACEBOOK_CONDITION,
  };
  return maps[platform][key] ?? fallback;
}

export function platformTitleLimit(platform: PlatformId): number | undefined {
  if (platform === "ebay") return 80;
  if (platform === "etsy") return 140;
  if (platform === "facebook") return 100;
  return undefined;
}

export function truncateTitle(title: string, max?: number): string {
  if (!max || title.length <= max) return title;
  return `${title.slice(0, max - 1).trimEnd()}…`;
}

import type { ListingDraft } from "./listing-draft.js";
import type { PricePrediction } from "./tabpfn-price.js";
import {
  PLATFORMS,
  type PlatformId,
  platformConditionLabel,
  platformTitleLimit,
  truncateTitle,
} from "../lib/platforms.js";

export type ListingFormField = {
  id: string;
  label: string;
  value: string;
  hint?: string;
  max_length?: number;
  multiline?: boolean;
};

export type ListingFormSection = {
  id: string;
  title: string;
  description?: string;
  fields: ListingFormField[];
};

export type PlatformListingPacket = {
  platform: PlatformId;
  label: string;
  tagline: string;
  sections: ListingFormSection[];
  copy_essentials_text: string;
};

export type ListingSetup = {
  default_platform: PlatformId;
  platforms: Array<{ id: PlatformId; label: string; tagline: string }>;
  price_fields: ListingFormSection;
  packets: Record<PlatformId, PlatformListingPacket>;
};

function field(
  id: string,
  label: string,
  value: string,
  opts?: { hint?: string; max_length?: number; multiline?: boolean },
): ListingFormField {
  return {
    id,
    label,
    value,
    hint: opts?.hint,
    max_length: opts?.max_length,
    multiline: opts?.multiline,
  };
}

function essentialsText(title: string, description: string): string {
  return `Title\n${title}\n\nDescription\n${description}`.trim();
}

function buildPriceFields(prediction: PricePrediction): ListingFormSection {
  return {
    id: "pricing",
    title: "List price (main value prop)",
    description:
      "Price Wire’s comp band for electronics in this condition. Paste into the marketplace price field—not into your description.",
    fields: [
      field("suggested_price", "Suggested", `$${prediction.suggested_price}`, {
        hint: "Starting ask from similar electronics sales in our sample pool",
      }),
      field("quick_sale_price", "Quick sale", `$${prediction.quick_sale_price}`, {
        hint: "Lower if you need a faster sale",
      }),
      field("hold_price", "Hold firm", `$${prediction.hold_price}`, {
        hint: "Higher if you can wait for the right buyer",
      }),
    ],
  };
}

function optionalSpecifics(draft: ListingDraft): string {
  const entries = Object.entries(draft.item_specifics);
  if (!entries.length) {
    return "Add brand/model in the marketplace form when prompted—category-specific fields vary by site.";
  }
  return entries.map(([k, v]) => `${k}: ${v}`).join("\n");
}

function coreCopySections(
  draft: ListingDraft,
  marketplaceConditionValue: string,
  platform: PlatformId,
): ListingFormSection[] {
  const cond = platformConditionLabel(platform, marketplaceConditionValue);
  const title = truncateTitle(draft.title, platformTitleLimit(platform));

  const sections: ListingFormSection[] = [
    {
      id: "listing_copy",
      title: "What to paste first",
      description:
        "Electronics listings win on search title, honest condition copy, and a fair price. Marketplace category specifics (MPN, carrier, etc.) come later in each site’s form.",
      fields: [
        field("title", "Title", title, {
          max_length: platformTitleLimit(platform),
          hint: "Search-friendly: brand, model, storage, unlocked—check character limit for this site",
        }),
        field("condition", "Condition", cond, {
          hint: "Pick the closest dropdown option on the marketplace",
        }),
        field("description", "Description", draft.description, {
          multiline: true,
          hint: "Condition-led story for buyers; add your shop policies before publishing",
        }),
      ],
    },
    {
      id: "optional_specifics",
      title: "Optional electronics specifics",
      description:
        "Only if the form asks—skip blanks you do not need. Full category catalogs are out of scope for this prototype.",
      fields: [
        field("item_specifics", "Starter specifics", optionalSpecifics(draft), {
          multiline: true,
          hint: "Edit or replace with what your category requires (phones vs consoles vs headphones)",
        }),
      ],
    },
  ];

  if (platform === "ebay") {
    const ship = draft.shipping;
    sections.push({
      id: "package_optional",
      title: "Package size (if prompted)",
      description:
        "Some eBay flows ask for weight or dimensions. Skip if you use a business shipping policy or flat rate.",
      fields: [
        field(
          "package_dims",
          "Dimensions (L × W × H)",
          `${ship.length_in} × ${ship.width_in} × ${ship.height_in} in`,
          { hint: "Estimate for packed box—measure yours before labels" },
        ),
        field("package_weight", "Weight", `~${ship.weight_lb} lb packed`, {
          hint: "Weigh after packing; carriers bill on actual weight",
        }),
      ],
    });
  }

  return sections;
}

function buildPacket(
  platform: PlatformId,
  meta: { label: string; tagline: string },
  sections: ListingFormSection[],
  title: string,
  description: string,
): PlatformListingPacket {
  return {
    platform,
    label: meta.label,
    tagline: meta.tagline,
    sections,
    copy_essentials_text: essentialsText(title, description),
  };
}

export function buildListingSetup(
  draft: ListingDraft,
  prediction: PricePrediction,
  marketplaceConditionValue: string,
): ListingSetup {
  const price_fields = buildPriceFields(prediction);
  const packets = {} as Record<PlatformId, PlatformListingPacket>;

  for (const meta of PLATFORMS) {
    const titleForCopy = truncateTitle(
      draft.title,
      platformTitleLimit(meta.id),
    );
    const sections = coreCopySections(
      draft,
      marketplaceConditionValue,
      meta.id,
    );
    packets[meta.id] = buildPacket(
      meta.id,
      meta,
      sections,
      titleForCopy,
      draft.description,
    );
  }

  return {
    default_platform: "ebay",
    platforms: PLATFORMS.map((p) => ({
      id: p.id,
      label: p.label,
      tagline: p.tagline,
    })),
    price_fields,
    packets,
  };
}

